    spread = jnp.sqrt(jnp.mean(centered**2, axis=-1, keepdims=True) + 1e-5)
    projected = (centered / spread * gamma) @ w_in + beta @ w_in
    hidden = jax.nn.gelu(projected) @ w_out
    return tokens + hidden
