def candidate(token_ids, table, gamma, beta, w_in, w_out):
    tokens = table[token_ids]
    mean = jnp.mean(tokens, axis=-1, keepdims=True)
    variance = jnp.maximum(jnp.mean(tokens * tokens, axis=-1, keepdims=True) - mean * mean, 0.0)
    spread = jnp.sqrt(variance + 1e-5)
    normalized = (tokens - mean) / spread * gamma + beta
    hidden = jax.nn.gelu(normalized @ w_in) @ w_out
    return tokens + hidden
