def candidate(signals):
    length = signals.shape[-1]
    radius = 16
    zero = jnp.zeros((signals.shape[0], 1), dtype=signals.dtype)
    prefix = jnp.concatenate((zero, jnp.cumsum(signals, axis=1)), axis=1)
    squared = signals * signals
    prefix_sq = jnp.concatenate((zero, jnp.cumsum(squared, axis=1)), axis=1)
    positions = jnp.arange(length)
    lo = jnp.maximum(positions - radius, 0)
    hi = jnp.minimum(positions + radius + 1, length)
    counts = (hi - lo).astype(signals.dtype)
    local_sum = prefix[:, hi] - prefix[:, lo]
    local_sq_sum = prefix_sq[:, hi] - prefix_sq[:, lo]
    mean = local_sum / counts[None, :]
    mean_square = local_sq_sum / counts[None, :]
    std = jnp.sqrt(jnp.maximum(mean_square - mean * mean, 0.0) + 1e-6)
    standardized = (signals - mean) / std
    peak = jnp.max(jnp.abs(standardized), axis=1, keepdims=True)
    return standardized / peak
