def candidate(signals):
    window = 33
    radius = window // 2
    kernel = jnp.ones((window,), dtype=signals.dtype)
    padded = jnp.pad(signals, ((0, 0), (radius, radius)))
    sums = jnp.sum(jax.lax.conv_general_dilated(
        padded[:, None, :],
        kernel[None, None, :],
        window_strides=(1,),
        padding='VALID',
        dimension_numbers=('NCH', 'OIH', 'NCH'),
    ), axis=1)
    squares = jnp.sum(jax.lax.conv_general_dilated(
        (padded * padded)[:, None, :],
        kernel[None, None, :],
        window_strides=(1,),
        padding='VALID',
        dimension_numbers=('NCH', 'OIH', 'NCH'),
    ), axis=1)
    indices = jnp.arange(signals.shape[-1])
    counts = jnp.minimum(indices + radius + 1, signals.shape[-1]) - jnp.maximum(indices - radius, 0)
    counts = counts.astype(signals.dtype)[None, :]
    mean = sums / counts
    variance = jnp.maximum(squares / counts - mean * mean, 0.0)
    standardized = (signals - mean) / jnp.sqrt(variance + 1e-6)
    peak = jnp.max(jnp.abs(standardized), axis=-1, keepdims=True)
    return standardized / peak
