def candidate(signals):
    length = signals.shape[-1]
    radius = 16
    zeros = jnp.zeros((signals.shape[0], 1), dtype=signals.dtype)
    prefix = jnp.concatenate((zeros, jnp.cumsum(signals, axis=-1)), axis=-1)
    prefix_sq = jnp.concatenate((zeros, jnp.cumsum(signals * signals, axis=-1)), axis=-1)
    indices = jnp.arange(length)
    lo = jnp.maximum(indices - radius, 0)
    hi = jnp.minimum(indices + radius + 1, length)
    sums = jnp.take(prefix, hi, axis=1) - jnp.take(prefix, lo, axis=1)
    square_sums = jnp.take(prefix_sq, hi, axis=1) - jnp.take(prefix_sq, lo, axis=1)
    counts = (hi - lo).astype(signals.dtype)[None, :]
    mean = sums / counts
    variance = jnp.maximum(square_sums / counts - mean * mean, 0.0)
    standardized = (signals - mean) / jnp.sqrt(variance + 1e-6)
    peak = jnp.max(jnp.abs(standardized), axis=-1, keepdims=True)
    return standardized / peak
